// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.documentimport timber.log.Timberimport com.roshan.persona.vision.ocr.BoundingBoximport com.roshan.persona.vision.ocr.GrayscaleImageimport com.roshan.persona.vision.ocr.RgbImage/** * NOUS — Edge Detector + Perspective Corrector (Module 6 v4 — Step 6.5). * * Implements document edge detection (4-corner) + perspective correction * (bird's-eye warp) + image enhancement via OpenCV4Android. * * ## Pipeline (per strategy v4 §"Architecture → DocumentScannerEngine") * * ``` * Raw image (12 MP) → *   ↓ * 1. Downsample to 720p working buffer (15 ms) *   ↓ * 2. Convert to grayscale (5 ms) *   ↓ * 3. Canny edge detection (20 ms) *   ↓ * 4. Find contours (15 ms) *   ↓ * 5. Approximate polygon → find 4-corner quadrilateral (10 ms) *   ↓ * 6. If 4 corners found → perspective warp to bird's-eye (30 ms) *    If not found → return original image (skip perspective) *   ↓ * 7. Adaptive threshold + CLAHE (40 ms) *   ↓ * 8. Return enhanced, perspective-corrected image * ``` * * Total budget: < 150 ms (per strategy v4 §"Performance Budgets"). * * ## Testability * * All OpenCV operations are abstracted via [EdgeDetectorDelegate] interface. * Production: [OpenCvEdgeDetector] wraps OpenCV4Android. * Tests: [FakeEdgeDetector] returns canned results. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Step 6.5: DocumentScannerEngine</a> */class EdgeDetector(    private val delegate: EdgeDetectorDelegate,) {    /**     * Detect the 4 corners of a document in [image].     *     * @param image the input image (RGB).     * @return the 4 corners (top-left, top-right, bottom-right, bottom-left),     *         or null if no quadrilateral detected.     */    suspend fun detectCorners(image: RgbImage): DocumentCorners? {        if (!delegate.isReady()) {            Timber.tag(TAG).w("Edge detector not ready.")            return null        }        return try {            delegate.detectCorners(image)        } catch (t: Throwable) {            Timber.tag(TAG).e("Edge detection failed", t)            null        }    }    /**     * Apply perspective correction to warp a document to bird's-eye view.     *     * @param image the input image.     * @param corners the 4 document corners.     * @param outputWidth output image width (default 1280).     * @param outputHeight output image height (default 720 for A4 landscape,     *                     or 720×1280 for portrait).     * @return the perspective-corrected image.     */    suspend fun correctPerspective(        image: RgbImage,        corners: DocumentCorners,        outputWidth: Int = 1280,        outputHeight: Int = 720,    ): RgbImage? {        return try {            delegate.warpPerspective(image, corners, outputWidth, outputHeight)        } catch (t: Throwable) {            Timber.tag(TAG).e("Perspective correction failed", t)            null        }    }    /**     * Full document scanning pipeline — detect corners + correct perspective + enhance.     *     * @param image the raw input image.     * @return the scanned (perspective-corrected + enhanced) image, or the     *         original if no document detected.     */    suspend fun scanDocument(image: RgbImage): ScannedDocument {        val startTime = System.currentTimeMillis()        // 1. Detect corners.        val corners = detectCorners(image)        // 2. If corners found, warp perspective.        val correctedImage = if (corners != null) {            correctPerspective(image, corners)        } else {            Timber.tag(TAG).d("No document corners detected — using original image.")            image        }        val elapsedMs = System.currentTimeMillis() - startTime        Timber.tag(TAG).i("Document scan: corners=${corners != null}, ${elapsedMs}ms.")        return ScannedDocument(            image = correctedImage ?: image,            cornersDetected = corners != null,            corners = corners,            processingTimeMs = elapsedMs,        )    }    /** True if the detector is ready. */    fun isReady(): Boolean = delegate.isReady()    private companion object {        private const val TAG = "EdgeDetector"    }}// ──────────────────────────────────────────────────────────────────────────/** The 4 corners of a detected document (normalized 0.0-1.0). */data class DocumentCorners(    val topLeft: DocumentPoint,    val topRight: DocumentPoint,    val bottomRight: DocumentPoint,    val bottomLeft: DocumentPoint,) {    /** Compute the bounding box of the 4 corners (normalized). */    val boundingBox: BoundingBox        get() = BoundingBox(            left = minOf(topLeft.x, bottomLeft.x),            top = minOf(topLeft.y, topRight.y),            right = maxOf(topRight.x, bottomRight.x),            bottom = maxOf(bottomLeft.y, bottomRight.y),        )    /** True if the corners form a roughly rectangular shape. */    val isRectangular: Boolean        get() {            // Check that adjacent edges are roughly perpendicular.            val topEdge = distance(topLeft, topRight)            val rightEdge = distance(topRight, bottomRight)            val bottomEdge = distance(bottomRight, bottomLeft)            val leftEdge = distance(bottomLeft, topLeft)            // Opposite edges should be roughly equal (within 30% tolerance).            val topBottomRatio = if (bottomEdge > 0) topEdge / bottomEdge else 0f            val leftRightRatio = if (rightEdge > 0) leftEdge / rightEdge else 0f            return topBottomRatio in 0.7f..1.3f && leftRightRatio in 0.7f..1.3f        }    /** Compute the area of the quadrilateral (shoelace formula). */    val area: Float        get() {            val pts = listOf(topLeft, topRight, bottomRight, bottomLeft)            var sum = 0f            for (i in pts.indices) {                val p1 = pts[i]                val p2 = pts[(i + 1) % pts.size]                sum += p1.x * p2.y - p2.x * p1.y            }            return kotlin.math.abs(sum / 2f)        }    private fun distance(a: DocumentPoint, b: DocumentPoint): Float {        val dx = b.x - a.x        val dy = b.y - a.y        return kotlin.math.sqrt(dx * dx + dy * dy)    }}/** A normalized (0.0-1.0) document corner point. */data class DocumentPoint(val x: Float, val y: Float) {    init {        require(x in 0f..1f) { "x must be 0-1: $x" }        require(y in 0f..1f) { "y must be 0-1: $y" }    }}/** Result of [EdgeDetector.scanDocument]. */data class ScannedDocument(    val image: RgbImage,    val cornersDetected: Boolean,    val corners: DocumentCorners?,    val processingTimeMs: Long,)// ──────────────────────────────────────────────────────────────────────────/** * Edge detector delegate interface — abstracts OpenCV for testability. * * Production: [OpenCvEdgeDetector] wraps OpenCV4Android * (org.opencv.android + org.opencv.imgproc). * Tests: [FakeEdgeDetector] returns canned corners + images. */interface EdgeDetectorDelegate {    /** Detect the 4 corners of a document in [image]. */    suspend fun detectCorners(image: RgbImage): DocumentCorners?    /** Warp [image] to bird's-eye view using [corners]. */    suspend fun warpPerspective(        image: RgbImage,        corners: DocumentCorners,        outputWidth: Int,        outputHeight: Int,    ): RgbImage?    /** True if OpenCV is loaded and ready. */    fun isReady(): Boolean}